// Draw spiral
let x = W/2, y = H/2;
let radius = 0;
const angleStep = 0.03;
const maxRadius = Math.min(W, H) / 2 - 20;

function drawSpiral() {
  if (radius > maxRadius) return;

  const angle = radius * 0.2;
  const step = 5 + Math.sin(radius * 0.1) * 5;

  const newX = x + Math.cos(angle) * radius;
  const newY = y + Math.sin(angle) * radius;

  // Draw gradient effect
  const gradient = ctx.createLinearGradient(x, y, newX, newY);
  gradient.addColorStop(0, colors[Math.floor(radius * 0.2)]);
  gradient.addColorStop(1, colors[Math.floor(radius * 0.2) + 1]);

  ctx.strokeStyle = gradient;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(newX, newY);
  ctx.stroke();

  x = newX;
  y = newY;
  radius += step;

  requestAnimationFrame(drawSpiral);
}

